            vec!["evidence://one".into()],
        )
        .unwrap();
        let changed_trace = CandidateSpec::new(
            json!({"model": "fixed"}),
            vec!["trace://two".into()],
            vec!["evidence://one".into()],
        )
        .unwrap();
        let changed_evidence = CandidateSpec::new(
            json!({"model": "fixed"}),
