        self.move_pane_focus(PaneDirection::Left);
    }

    pub fn focus_pane_right(&mut self) {
        self.move_pane_focus(PaneDirection::Right);
    }

    pub fn focus_pane_up(&mut self) {
        self.move_pane_focus(PaneDirection::Up);
