        }

        self.search_input = Some(self.search_query.clone().unwrap_or_default());
        let mode = if self.output_mode == OutputMode::ContextGraph {
            "graph search"
        } else {
            "search"
        };
        self.set_operator_note(format!("{mode} mode | type a query and press Enter"));
    }

