fn sort_sessions_for_display(sessions: &mut [Session]) {
    sessions.sort_by(|left, right| {
        left.project
            .cmp(&right.project)
            .then_with(|| left.task_group.cmp(&right.task_group))
            .then_with(|| right.updated_at.cmp(&left.updated_at))
            .then_with(|| left.id.cmp(&right.id))
    });
}

