        );
        let patch = "--- Branch diff vs main ---\n\
diff --git a/src/lib.rs b/src/lib.rs\n\
@@ -1 +1 @@\n\
-old line\n\
+new line"
            .to_string();
        dashboard.selected_diff_summary = Some("1 file changed".to_string());
