            BudgetState::Alert90
        );
        assert_eq!(
            TokenMeter::tokens("Token Budget", 100, 100, Config::BUDGET_ALERT_THRESHOLDS).state(),
            BudgetState::OverBudget
        );
    }

    #[test]
    fn gradient_runs_from_green_to_yellow_to_red() {
